WITH with_windows AS (SELECT *, AVG(unit_price) OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS unit_price_avg_2, ROUND(quantity / SUM(quantity) OVER (PARTITION BY order_id), 4) AS quantity_share, NTILE(10) OVER w_ordered AS unit_price_bucket FROM order_items WHERE product_id IN (35, 37, 38) WINDOW w_ordered AS (PARTITION BY product_id, order_id ORDER BY unit_price, id)), joined AS (SELECT e.id, e.product_id, e.unit_price, b.product_name, b.price, b.stock_qty FROM with_windows e JOIN products b ON e.product_id = b.id), scored AS (SELECT id, price, LAG(unit_price, 1) OVER (PARTITION BY product_id ORDER BY price, id) AS prev_unit_price, LEAD(unit_price, 1) OVER (PARTITION BY product_id ORDER BY unit_price, id) AS next_unit_price FROM joined), filtered AS (SELECT *, FLOOR(prev_unit_price) AS prev_unit_price_whole FROM scored WHERE price <= 950) SELECT id, price, prev_unit_price, next_unit_price, prev_unit_price_whole FROM filtered;
